import { Decoration, MatchDecorator, ViewPlugin, type EditorView, type ViewUpdate } from '@codemirror/view';

// Mask placeholders are generated by privacy.ts. Highlight the complete JSON
// string so the user can distinguish transformed data from untouched content.
const matcher = new MatchDecorator({
  regexp: /"\[(?:redacted|redacted_key|email|phone|id|card|ip)\]"/g,
  decoration: () => Decoration.mark({ class: 'cm-masked-token' }),
});

export const maskedHighlights = ViewPlugin.fromClass(class {
  decorations;
  constructor(view: EditorView) { this.decorations = matcher.createDeco(view); }
  update(update: ViewUpdate) { this.decorations = matcher.updateDeco(update, this.decorations); }
}, { decorations: plugin => plugin.decorations });
